local TextChatService = game:GetService("TextChatService")
local RBXGeneral = TextChatService:WaitForChild("TextChannels"):WaitForChild("RBXGeneral")

local function say(t)
	RBXGeneral:SendAsync(tostring(t))
end

local function getPlayer(query)
	local Players = PlayersService:GetPlayers()

	for _, player in pairs(Players) do
		if (type(query) == "number" and player.UserId == query) or (type(query) == "string" and player.name:lower() == query:lower()) then
			return player
		end
	end

	for _, player in pairs(Players) do
		if type(query) == "string" and player.name:lower():find(query:lower()) then
			return player
		end
	end
end

local function shuffleTable(t)
    local n = #t
    for i = n, 2, -1 do
        local j = math.random(i)
        t[i], t[j] = t[j], t[i]
    end
end

local OnMessage = {}

local function WaitForMessage(predicate, timeout)
	local message = nil
	local start = os.time()

	table.insert(OnMessage, {
		callback = function(m)
			message = m	
		end,
		predicate = predicate,
		once = true
	})

	repeat wait() until message or os.time() > (start + timeout)

	return message
end

