local function runQuiz(quiz, subject)
	say("✨ | A " .. subject .. " quiz has been started! To answer a question, simply type your answer in chat. If I don't respond, your answer was incorrect.")

	shuffleTable(quiz)

	local leaderboard = {}

	for i, v in pairs(quiz) do
		say("🎙 | " .. v.question)

		local winner = WaitForMessage(function(message)
			return (type(v.answer) == "string" and message.Text:lower() == v.answer:lower()) or (type(v.answer) == "table" and table.find(v.answer, message.Text:lower()))
		end, configuration.timeout)

		if winner then
			winner = getPlayer(winner.TextSource.UserId)

			if winner then
				local added = false

				for _, e in pairs(leaderboard) do
					if e.player.id == winner.UserId then
						e.points = e.points + 1
					end
				end

				if not added then
					table.insert(leaderboard, {player = {name = winner.Name, id = winner.UserId}, points = 1})
				end

				say("✅ | " .. winner.Name .. " answered the question correctly! They have earned one point.")
			end
		else
			say("❌ | Moving on, nobody answered correctly within " .. configuration.timeout .. " seconds. The answer was: " .. ((type(v.answer) == "string" and v.answer) or (type(v.answer) == "table" and table.concat(v.answer, ", "))))
		end
	end

	table.sort(leaderboard, function(a,b)
		return a.points > b.points
	end)

	if leaderboard and leaderboard[1] then
		say("🥇 | " .. leaderboard[1].player.name .. " won with " .. leaderboard[1].points .. " points!")
	else
		say("❌ | Nobody won this round.")
	end

	say("💖 | Thanks for playing!")
end

